code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not cells:
        return [row[:] for row in grid]
    row_counts = [sum(v != 0 for v in row) for row in grid]
    if max(row_counts) >= max(3, int(0.7 * w)):
        source_key = lambda r, c: r
        output_key = lambda r, c: r
        mode = 'row'
    else:
        minus, plus = {}, {}
        for r, c, v in cells:
            minus[c-r] = minus.get(c-r, 0) + 1
            plus[r+c] = plus.get(r+c, 0) + 1
        score_minus = sum(n*n for n in minus.values())
        score_plus = sum(n*n for n in plus.values())
        if score_minus >= score_plus:
            source_key = lambda r, c: c-r
        else:
            source_key = lambda r, c: r+c
        output_key = lambda r, c: c-r
        mode = 'diag'
    observed = {}
    for r, c, v in cells:
        k = source_key(r, c)
        if k not in observed or observed[k] == v:
            observed[k] = v
    period = 1
    while period <= max(h, w):
        residues = {}
        conflict = False
        for k, v in observed.items():
            q = k % period
            if q in residues and residues[q] != v:
                conflict = True
                break
            residues[q] = v
        if not conflict:
            break
        period += 1
    residues = {k % period: v for k, v in observed.items()}
    return [[residues.get(output_key(r, c) % period, 0) for c in range(w)] for r in range(h)]
'''
